using Studio.Core;
using Studio.Raple;
var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
const string entity="Cave Pirate Brawler";var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var original=File.ReadAllText(file);
const string source="""
using TKR.WorldServer.logic.behaviors;
using TKR.WorldServer.logic.transitions;
namespace TKR.WorldServer.logic{public partial class BehaviorDb{
    private _ StudioPacketOrigin=()=>Behav().Init("Cave Pirate Brawler",new State(new State("go",new Shoot(20,count:3,fixedAngle:0,coolDown:100),new Shoot(20,count:5,fixedAngle:0,coolDown:100),new TimedTransition(0,"wait")),new State("wait")));
}}
""";
var document=new BehaviorDocument(source,adapter,sourceFile:file);var project=new StudioProject{SourceFile=file,Source=source,EntityId=entity,Identities=document.Identities,Player=new(Invulnerable:true),Seed=7};Emission[] shots=[];
await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project))
{
    native.Recording=new(native);await native.AdvanceAsync(new(),100);shots=native.Shots.ToArray();var attacks=native.Events.Where(e=>e.Kind=="attack").ToArray();
    Check(native.Stamp.Source.PacketInstrumentation&&attacks.Length==2&&attacks.All(e=>e.PacketOrigin!=null),"Actual acknowledgement enqueue supplies causal metadata for both identical-index attacks");
    Check(attacks.Select(e=>e.NodeId).SequenceEqual(document.AllNodes.Where(n=>n.Kind=="Shoot").Select(n=>(Guid?)n.Id)),"Same-phase same-projectile actions retain their distinct actual emitting constructor identities");
    Check(attacks.All(e=>e.PhaseOrigin?.TryResolve(project,out _)==true)&&native.Entities.Single().Phase=="wait", "Attack observations retain post-tick phase separately from the emitting action");
    Check(attacks.All(e=>e.PacketOrigin!.Source?.TryResolve(project,out _)==true&&e.PacketOrigin.Stage=="Tick"&&e.PacketOrigin.CallbackActorId==e.ActorId),"Causal source, native callback stage and controller actor survive the worker boundary");
    Check(attacks.Select(e=>e.PacketIndex).SequenceEqual(new int?[]{0,1})&&attacks.All(e=>native.Callbacks.Any(c=>c.Sequence==e.PacketOrigin!.CallbackSequence&&c.Origin==e.PacketOrigin.Source)),"Raw packet indices link attacks to exact nested callback transcript entries");
    var tape=EncounterReplay.Capture(project,null,EncounterReplay.Identify(adapter,project,native.Stamp.BuildId),native);var replay=await ReplayCursor.RestoreAsync(adapter,tape,100);Check(replay.Session.Events.SequenceEqual(tape.Events),"Replay reproduces complete causal attack events");replay.Session.Dispose();
    var changed=tape.Events.ToArray();var index=Array.FindIndex(changed,e=>e.Kind=="attack");changed[index]=changed[index] with{PacketOrigin=changed[index].PacketOrigin! with{CallbackSequence=999}};var rejected=false;try{var bad=await ReplayCursor.RestoreAsync(adapter,tape with{Events=changed},100);bad.Session.Dispose();}catch(InvalidOperationException){rejected=true;}Check(rejected,"Replay rejects altered emission-to-callback links");
}
await using(var plain=await CompiledRuntime.StartAsync(adapter.ServerRoot,project,captureStateOrigins:false)){await plain.AdvanceAsync(new(),100);Check(plain.Shots.SequenceEqual(shots)&&plain.Events.Where(e=>e.Kind=="attack").All(e=>e.PacketOrigin==null),"Uninstrumented original execution retains identical physical packets and an explicit causal boundary");}
const string effectSource="""
using TKR.WorldServer.logic.behaviors;
using TKR.WorldServer.core.objects;
using TKR.WorldServer.core.worlds;
using TKR.WorldServer.networking.packets.outgoing;
namespace TKR.WorldServer.logic{public partial class BehaviorDb{
    private _ StudioPacketEffects=()=>Behav().Init("Cave Pirate Brawler",new State("motion",new StudioPacketWrapper(new StudioPacketEmitter(100),new StudioPacketEmitter(200))));
    static readonly ShowEffect StudioReusedEffect=new ShowEffect{EffectType=EffectType.LedgerMark};
    sealed class StudioPacketWrapper:Behavior{readonly Behavior first,second;public StudioPacketWrapper(Behavior first,Behavior second){this.first=first;this.second=second;}protected override void TickCore(Entity host,TickTime time,ref object state){first.Tick(host,time);second.Tick(host,time);}}
    sealed class StudioPacketEmitter:Behavior{readonly int duration;public StudioPacketEmitter(int duration)=>this.duration=duration;protected override void TickCore(Entity host,TickTime time,ref object state){StudioReusedEffect.TargetObjectId=host.Id;StudioReusedEffect.Duration=duration;host.World.BroadcastIfVisible(StudioReusedEffect,host);}}
}}
""";
var effectDoc=new BehaviorDocument(effectSource,adapter,sourceFile:file);var effectProject=project with{Source=effectSource,Identities=effectDoc.Identities};NativeEffect[] effects=[];
await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,effectProject)){native.Recording=new(native);await native.AdvanceAsync(new(),100);effects=native.Effects.ToArray();var events=native.Events.Where(e=>e.Kind=="effect").ToArray();Check(events.Length==2&&events.All(e=>e.PacketOrigin?.Source!=null),"Actual transport enqueues attribute both reused-object effects to their emitting callbacks");Check(events.Select(e=>e.NodeId).SequenceEqual(effectDoc.AllNodes.Where(n=>n.Kind.EndsWith("StudioPacketEmitter")).Select(n=>(Guid?)n.Id)),"Repeated sends of one packet object retain FIFO occurrence provenance without overwriting earlier sources");Check(events.All(e=>native.Callbacks.Any(c=>c.Sequence==e.PacketOrigin!.CallbackSequence&&c.ParentSequence!=null)),"Nested helper effect emissions link the innermost dispatcher rather than its parent wrapper");Check(events.Select(e=>e.PacketIndex).SequenceEqual(new int?[]{0,1}),"Effect events retain exact observed raw packet indices");var tape=EncounterReplay.Capture(effectProject,null,EncounterReplay.Identify(adapter,effectProject,native.Stamp.BuildId),native);var replay=await ReplayCursor.RestoreAsync(adapter,tape,100);Check(replay.Session.Events.SequenceEqual(tape.Events)&&replay.Session.Effects.SequenceEqual(tape.Effects),"Replay preserves reused-packet metadata and actual native payload semantics");replay.Session.Dispose();}
await using(var plain=await CompiledRuntime.StartAsync(adapter.ServerRoot,effectProject,captureStateOrigins:false)){await plain.AdvanceAsync(new(),100);Check(plain.Effects.SequenceEqual(effects),"Causal observation preserves uninstrumented effect payloads, including original mutable-packet queue behavior");}
const string laneSource="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioPacketLanes=()=>Behav().Init(\"Cave Pirate Brawler\",new State(\"lanes\",new OwnedLaneEmitters(\"Gordo Procession Emitter\",LaneAxes.Cross,intervalMs:200,startupMs:200)));}}";
var laneDoc=new BehaviorDocument(laneSource,adapter,sourceFile:file);await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=laneSource,Identities=laneDoc.Identities})){await native.AdvanceAsync(new(),500);var packets=native.Events.Where(e=>e.Kind is "attack" or "effect").ToArray();Check(packets.Any(e=>e.PacketOrigin?.Behavior.EndsWith("LaneEmission")==true)&&packets.Where(e=>e.PacketOrigin!=null).All(e=>e.PacketOrigin!.Source==null&&e.PacketOrigin.CallbackActorId==e.ActorId),"Original owned helper emissions retain their actual LaneEmission dispatcher and explicit unaccepted-construction boundary");}
var remoteSource=effectSource.Replace("StudioReusedEffect.TargetObjectId=host.Id","StudioReusedEffect.TargetObjectId=System.Linq.Enumerable.First(host.World.Enemies.Values,e=>e.Id!=host.Id).Id").Replace("host.World.BroadcastIfVisible(StudioReusedEffect,host)","host.World.BroadcastIfVisible(new ShowEffect{EffectType=EffectType.LedgerMark,TargetObjectId=StudioReusedEffect.TargetObjectId,Duration=duration},host)");var remoteDoc=new BehaviorDocument(remoteSource,adapter,sourceFile:file);await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=remoteSource,Identities=remoteDoc.Identities,Arena=new(){Actors=[new(entity,66.5,64.5)]}})){await native.AdvanceAsync(new(),100);Check(native.Events.Where(e=>e.Kind=="effect").All(e=>e.PacketOrigin?.Source!=null&&e.ActorId!=e.PacketOrigin.CallbackActorId),"Remote-target packets distinguish target actor identity from the actual source controller actor");}
const string reusedShotSource="""
using TKR.WorldServer.core.objects;using TKR.WorldServer.core.worlds;using TKR.WorldServer.networking.packets.outgoing;using System.Linq;
namespace TKR.WorldServer.logic{public partial class BehaviorDb{
    private _ StudioReusedShotFixture=()=>Behav().Init("Cave Pirate Brawler",new State("motion",new StudioReusedShotController(new StudioShotSender(),new StudioShotSender())));
    static readonly EnemyShootMessage StudioSharedShot=new EnemyShootMessage{NumShots=1,BulletType=0,Damage=1};
    sealed class StudioReusedShotController:Behavior{readonly Behavior first,second;public StudioReusedShotController(Behavior first,Behavior second){this.first=first;this.second=second;}protected override void TickCore(Entity host,TickTime time,ref object state){first.Tick(host,time);var player=host.World.Players.Values.Single();var queue=typeof(Player).GetField("PendingShootAcknowlegements",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(player);queue.GetType().GetMethod("Clear").Invoke(queue,null);second.Tick(host,time);}}
    sealed class StudioShotSender:Behavior{protected override void TickCore(Entity host,TickTime time,ref object state){StudioSharedShot.OwnerId=host.Id;StudioSharedShot.ObjectType=host.ObjectType;StudioSharedShot.BulletId=host.GetNextBulletId(1);StudioSharedShot.StartingPos=new TKR.WorldServer.core.structures.Position(host.X,host.Y);host.World.Players.Values.Single().EnemyShoot(StudioSharedShot);}}
}}
""";
var reusedShotDoc=new BehaviorDocument(reusedShotSource,adapter,sourceFile:file);await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=reusedShotSource,Identities=reusedShotDoc.Identities})){await native.AdvanceAsync(new(),100);var attack=native.Events.Single(e=>e.Kind=="attack");Check(native.Shots.Count==1&&attack.PacketOrigin?.Source?.Start==reusedShotSource.LastIndexOf("new StudioShotSender()",StringComparison.Ordinal),"Acknowledgement-object provenance cannot retain a discarded occurrence when the same shot packet is sent again");}
